export interface NetworkInformation {
  downlink?: number;
  downlinkMax?: number;
  effectiveType?: "2g" | "3g" | "4g" | "slow-2g";
  rtt?: number;
  saveData?: boolean;
  type?:
    | "bluetooth"
    | "cellular"
    | "ethernet"
    | "none"
    | "wifi"
    | "wimax"
    | "other"
    | "unknown";
}

export interface UseNetworkInformationReturn {
  /** Detailed information about the network connection. */
  networkInfo: NetworkInformation | null;
  /** Whether the browser detects an internet connection. */
  isOnline: boolean;
  /** Whether the Network Information API is supported in this browser. */
  isSupported: boolean;
  /** Function to manually update the network information. */
  refresh: () => void;
}

declare global {
  interface Navigator {
    connection?: NetworkInformation;
  }
}

/**
 * Custom hook that tracks the device's network connection status and details (speed, type)
 * using the Network Information API.
 * @category network
 * @returns {UseNetworkInformationReturn} The network state, connection details, and support status.
 * @public
 * @see [Documentation](/docs/use-network-information)
 * @example
 * ```tsx
 * const { isOnline, networkInfo } = useNetworkInformation();
 * if (!isOnline) return <div>You are offline</div>;
 * return (
 * <div>
 * Connection: {networkInfo?.effectiveType} ({networkInfo?.downlink} Mbps)
 * </div>
 * );
 * ```
 */
export const useNetworkInformation = (): UseNetworkInformationReturn => {
  const [networkInfo, setNetworkInfo] = useState<NetworkInformation | null>(
    null,
  );

  const [isOnline, setIsOnline] = useState<boolean>(
    typeof navigator !== "undefined" ? navigator.onLine : true,
  );

  const isSupported =
    typeof navigator !== "undefined" &&
    "connection" in navigator &&
    navigator.connection !== undefined;

  const updateNetworkInfo = useCallback(() => {
    if (!isSupported || !navigator.connection) return;

    const connection = navigator.connection;

    setNetworkInfo({
      downlink: connection.downlink,
      downlinkMax: connection.downlinkMax,
      effectiveType: connection.effectiveType,
      rtt: connection.rtt,
      saveData: connection.saveData,
      type: connection.type,
    });
  }, [isSupported]);

  const handleOnlineStatusChange = useCallback(() => {
    setIsOnline(navigator.onLine);
  }, []);

  const handleConnectionChange = useCallback(() => {
    updateNetworkInfo();
  }, [updateNetworkInfo]);

  useEffect(() => {
    if (typeof window === "undefined") return;

    updateNetworkInfo();

    window.addEventListener("online", handleOnlineStatusChange);
    window.addEventListener("offline", handleOnlineStatusChange);

    if (isSupported) {
      const connection = (navigator as any).connection;
      connection.addEventListener("change", handleConnectionChange);
    }

    return () => {
      window.removeEventListener("online", handleOnlineStatusChange);
      window.removeEventListener("offline", handleOnlineStatusChange);

      if (isSupported) {
        const connection = (navigator as any).connection;
        connection.removeEventListener("change", handleConnectionChange);
      }
    };
  }, [
    isSupported,
    updateNetworkInfo,
    handleOnlineStatusChange,
    handleConnectionChange,
  ]);

  return {
    networkInfo,
    isOnline,
    isSupported,
    refresh: updateNetworkInfo,
  };
};

